    variantValues?: {
        [key: string]: unknown;
    } | null;
    /**
     * The SKU's storage class (FR-40): ambient, chilled, frozen, controlled, hazardous or secure. Omit to leave unchanged.
     */
    storageClass?: 'ambient' | 'chilled' | 'frozen' | 'controlled' | 'hazardous' | 'secure';
