export type RecordPickDto = {
    /**
     * Warehouse the pick draws from
     */
    warehouseId: string;
    /**
     * The picklist whose walk is being executed
     */
    picklistId: string;
    /**
     * The pick line being drawn (one slice of one order line)
     */
    picklistLineId: string;
    /**
     * The SKU the operator scanned — verified against the line
     */
    skuId: string;
    /**
     * The bin the operator scanned — checked against live stock, not against the plan
     */
    binId: string;
    /**
     * Units actually drawn in base UoM. Equal to the line’s planned quantity for an ordinary pick; BELOW it (down to 0, an empty bin) for a short pick, which must carry a reasonCode. Above the plan is always a 400. A quantity in the SKU's base UoM, at the decimal precision that unit declares (each = 0 places, kg = 3). A value finer than its unit allows is refused, naming the unit and its precision — never silently rounded.
     */
    qty: number;
    /**
     * Device time of the pick (ISO-8601 UTC, Z-suffixed)
     */
    occurredAt: string;
    /**
     * The serial numbers of a serial-tracked pick (one per drawn unit, no duplicates)
     */
    serials?: Array<string>;
    /**
     * Story 4.3b (AD-14): the scanned bin’s state_epoch as the device read it from the sealed snapshot at task start. Opaque and compared only for equality — never interpreted. Omit it (or send null) and the replay behaves exactly as it did before this story: a device whose cache predates the field is never refused for the absence of it.
     */
    binStateEpoch?: number | null;
    /**
     * Story 4.4: why this stop came up short. REQUIRED whenever qty is below the line’s planned quantity (including 0), refused outside the fixed set with a 400 naming the whole set, and ignored when qty equals the plan (that is an ordinary full pick). It is part of the idempotency payload hash — the reason is intent, not an observation. Story 3-3b: `skipped-blocked-bin` skips a planned stop whose bin is now blocked — only with qty 0 at the stop's own bin (else 400 validation-failed) and only while the bin is blocked (else 409 bin-not-blocked); it re-plans the stop onto other bins and needs no bin scan.
     */
    reasonCode?: 'bin-empty' | 'fewer-units-than-planned' | 'damaged-units' | 'stock-not-found' | 'other' | 'skipped-blocked-bin';
};

export type ReplannedSliceDto = {
    /**
     * The NEW pick line carrying the remainder
     */
    picklistLineId: string;
    /**
     * The alternate bin — never the bin that came up short
     */
    binId: string;
    /**
     * The alternate bin’s code — the walk key
     */
    binCode: string;
    /**
     * FEFO batch suggestion; null when untracked
     */
    batchId: string | null;
    /**
     * Units to draw at the alternate bin
     */
    qty: number;
    /**
     * The order line’s next unused slice index
     */
    sliceSeq: number;
    /**
     * Walk position — after every stop the picklist already had
     */
    walkSeq: number;
};

export type PickDto = {
    /**
     * The picks row id — NULL on a zero-unit short pick (story 4.4), which writes no picks row at all: nothing moved, so there is no ledger event and no settlement record. Every other pick, short or whole, has one.
     */
    id: string | null;
    tenantId: string;
    warehouseId: string;
    waveId: string;
    picklistId: string;
    picklistLineId: string;
    orderId: string;
    orderLineId: string;
    skuId: string;
    skuCode: string;
    /**
     * The bin the units were actually drawn from
     */
    binId: string;
    binCode: string;
    /**
     * The plan’s suggested bin (advisory)
     */
    suggestedBinId: string | null;
    suggestedBinCode: string | null;
    /**
     * The batch re-derived FEFO in the scanned bin; null when untracked or when the draw spanned several batches
     */
    batchId: string | null;
    batchCode: string | null;
    /**
     * The plan’s suggested batch (advisory)
     */
    suggestedBatchId: string | null;
    /**
     * The plan’s suggested batch code — paired with the id, like the bin arms
     */
    suggestedBatchCode: string | null;
    /**
     * Units drawn (base UoM)
     */
    qty: number;
    /**
     * The order line’s journal hold
     */
    reservationId: string | null;
    /**
     * True when this pick settled the hold (held → committed) in the same transaction as the draw
     */
    reservationCommitted: boolean;
    /**
     * The pick line’s status after the pick — picked on a whole-quantity draw, short (story 4.4, terminal) when the operator drew fewer units than the stop planned
     */
    lineStatus: 'planned' | 'unfulfillable' | 'picked' | 'short' | 'cancelled';
    /**
     * Units the stop planned but never moved — 0 on a whole-quantity pick
     */
    shortfallQty: number;
    /**
     * Why the stop came up short (story 4.4); null on a whole-quantity pick
     */
    reasonCode: 'bin-empty' | 'fewer-units-than-planned' | 'damaged-units' | 'stock-not-found' | 'other' | 'skipped-blocked-bin' | null;
    /**
     * True when this command RELEASED the order line’s hold (story 4.4): a short pick releases the whole hold and re-grants the remainder, because reservations are whole-quantity rows with no partial commit
     */
    reservationReleased: boolean;
    /**
     * The fresh hold covering everything the order line still owes after the release — null when there was no remainder, or when it could not be re-held (the partial-order path). The re-planned slices and every still-open sibling slice carry it.
     */
    replanReservationId: string | null;
    /**
     * The new slices the remainder was re-planned onto — empty on the partial-order path
     */
    replanned: Array<ReplannedSliceDto>;
    pickedBy: string;
    /**
     * Device time of the pick (AD-1)
     */
    pickedAt: string;
    deviceId: string;
    /**
     * ISO-8601 UTC server record time
     */
    createdAt: string;
    /**
     * Story 4.3b (AD-14): the taxonomy arm this pick settled under — none (no epoch sent, or the bin’s epoch still matched), applied (the epoch had moved and the draw stood on its own), settled (the moved-on bin still covered the draw and this pick settled the order line’s hold). The taxonomy’s two refusal arms write nothing, so they never appear here.
     */
    conflictClass: 'none' | 'applied' | 'settled';
};

export type PickResponse = {
    pick: PickDto;
};

