export type InventoryControllerListEventsData = {
    body?: never;
    path: {
        /**
         * Owning tenant (must match the session)
         */
        tenantId: string;
        warehouseId: string;
    };
    query?: {
        /**
         * Story 1-5a — only events of one client's SKUs. An unknown id is an empty page
         */
        clientId?: string;
        /**
         * Only events of one SKU
         */
        skuId?: string;
        /**
         * Only events touching one bin (its source OR destination; story 5-4's bin-history read)
         */
        binId?: string;
        /**
         * Story 9-1 — only events of these types (repeatable: `?type=a&type=b`; one value is a one-element list). An unknown type is refused (400 validation-failed naming the known set)
         */
        type?: Array<'stock.adjusted' | 'grn.received' | 'qc.held' | 'qc.released' | 'putaway.placed' | 'bin.merged' | 'pick.picked' | 'pick.restocked' | 'pack.packed' | 'dispatch.dispatched' | 'excursion.recorded' | 'transfer.outbound' | 'transfer.inbound' | 'return.received' | 'grn.damaged' | 'qc.failed' | 'stock.moved' | 'return.restocked' | 'return.scrapped' | 'return.reversed' | 'rtv.dispatched' | 'rtc.dispatched'>;
        /**
         * Story 9-1 — only events RECORDED at or after this instant (`recorded_at` — the server stamp, never the device `occurred_at`). ISO-8601 with a zone designator
         */
        from?: string;
        /**
         * Story 9-1 — only events RECORDED strictly before this instant (exclusive). Must be after `from`
         */
        to?: string;
        /**
         * Story 9-1 — only events whose reference document names this order (`referenceDoc.orderId` — the pick, pack and dispatch arms)
         */
        orderId?: string;
        /**
         * Story 9-1 — `true`: only short-pick draws (`referenceDoc.shortPick`); `false`: only events that are not. Exactly 'true' or 'false'
         */
        shortPick?: boolean;
        /**
         * Story 9-3a — only events of this goods receipt (`referenceDoc.grnId`): its receipt events AND its putaway placements
         */
        grnId?: string;
        /**
         * Story 9-3a — only events naming this purchase order (`referenceDoc.poId`): its RECEIPT events only — a putaway names its GRN, not the PO
         */
        poId?: string;
        /**
         * Story 9-3a — only events of this transfer order (`referenceDoc.transferId`) on this warehouse — both legs on its chain
         */
        transferId?: string;
        /**
         * Story 9-3a — only the events an approval posted for this pending adjustment (`referenceDoc.adjustmentPendingId`; approvals from 9-3a on)
         */
        adjustmentPendingId?: string;
        /**
         * Story 9-3a — only the correction an approve-adjust resolution posted for this count variance (`referenceDoc.countVarianceId`; resolutions from 9-3a on)
         */
        countVarianceId?: string;
        /**
         * Opaque keyset cursor from the previous page
         */
        cursor?: string;
        limit?: number;
    };
    url: '/tenants/{tenantId}/warehouses/{warehouseId}/inventory/events';
};

