export type ReplenishmentControllerListBatchAlertsData = {
    body?: never;
    path: {
        /**
         * Owning tenant (must match the session)
         */
        tenantId: string;
    };
    query?: {
        /**
         * Story 1-5a — only alerts on one client's SKUs. An unknown id is an empty page
         */
        clientId?: string;
        /**
         * Only alerts of one kind (the queue's kind filter — a batch can carry both)
         */
        kind?: 'expiry_upcoming' | 'aged';
        /**
         * Only alerts of one status (the lifecycle tabs; the ops queue reads open)
         */
        status?: 'open' | 'resolved' | 'dismissed';
        /**
         * Only one warehouse's alerts
         */
        warehouseId?: string;
        /**
         * Story 9-1 — only alerts raised (`created_at`, server time) at or after this instant. ISO-8601 with a zone designator
         */
        from?: string;
        /**
         * Story 9-1 — only alerts raised strictly before this instant (exclusive). Must be after `from`
         */
        to?: string;
        /**
         * Opaque keyset cursor from the previous page
         */
        cursor?: string;
        limit?: number;
    };
    url: '/tenants/{tenantId}/replenishment/batch-alerts';
};

